func:
// For each sensor uplink LORIOT sends "rx", then "txd" (its downlink to the
// sensor), then "gw" (the same uplink plus gateway info). Aloxy Core's
// /lns/loriot endpoint accepts "gw" and rejects "rx" (tested 2026-10-13),
// so forward only "gw" and drop the rest.
let m = msg.payload;
if (typeof m === "string") {
    try { m = JSON.parse(m); } catch (e) { return null; }
}
if (m.cmd !== "gw" || !m.data) return null;
node.status({ fill: "green", shape: "dot", text: m.EUI + " @ " + new Date().toLocaleTimeString() });
return {
    url: "http://aloxy-core:8080/core/calculate/lns/loriot",
    method: "POST",
    headers: { "Content-Type": "application/json" },
    payload: m
};
